# Generated by build.py from recipe.yml for recipe smtp-check-the-mail-an-app-sent. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'signup.eml'), "From: app@example.com`nTo: ann@example.com`nSubject: Welcome to Example`n`nThanks for signing up.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'bad-subject.eml'), "From: app@example.com`nTo: bob@example.com`nSubject: Welcome to Exmaple`n`nThanks for signing up.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'bad-from.eml'), "From: noreply@example.org`nTo: bob@example.com`nSubject: Welcome to Example`n`nThanks for signing up.`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -T signup.eml smtp://127.0.0.1:8080/example.com --next -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=HEADER.FIELDS%20(FROM%20TO%20SUBJECT)" } finally { Stop-Process $server0 }
